?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Mi espacio de negocios | Explorando Lugares</title><link rel="stylesheet" href="<?=esc(site_path('/assets/style.css?v=business-portal-2'))?>"><link rel="stylesheet" href="<?=esc(site_path('/assets/admin.css?v=business-payments-1'))?>"><link rel="icon" href="<?=esc(site_path('/assets/favicon.svg'))?>" type="image/svg+xml"></head><body><?php require __DIR__.'/../_account-header.php'; ?><main class="wrap admin-page account-portal" data-plan-prices="<?=esc((string)$paymentPrices)?>" data-plan-requirements="<?=esc((string)$paymentRequirements)?>"><a class="brand" href="<?=esc(site_path('/index.html'))?>"><img class="brand-logo" src="<?=esc(site_path('/assets/logo.svg'))?>" alt="" width="64" height="64"><span>Explorando<b>Lugares</b></span></a><div class="account-portal-top"><div><p class="eyebrow">Espacio para negocios</p><h1>Hola, <?=esc($account['display_name'])?></h1><p><?=esc($account['email'])?></p></div></div><?php if(($_GET['solicitud']??'')==='recibida'):?><p class="notice" role="status"><strong>Cuenta creada y solicitud recibida.</strong> La revisaremos antes de asociar el negocio o preparar su página pública.</p><?php endif ?><p class="notice">Tu cuenta solo administra negocios cuya relación haya sido validada y autorizada.</p>
<section class="destination-admin-list"><h2>Negocios que administras</h2><?php if(!$businesses):?><p>Aún no hay negocios autorizados para administrar.</p><?php else:?><div class="destination-admin-table"><table><thead><tr><th>Negocio</th><th>Destino</th><th>Verificación</th><th>Publicación</th><th>Suscripción</th></tr></thead><tbody><?php foreach($businesses as $business):?><tr><td><?=esc($business['display_name'])?></td><td><?=esc($business['destination_name'])?></td><td><?=esc($business['information_status'])?></td><td><?=esc($business['publication_status'])?></td><td><?=esc($business['plan_code']??'Sin seleccionar')?> · <?=esc($business['subscription_status']??'Pendiente')?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
<section class="destination-admin-list"><h2>Solicitudes asociadas a tu cuenta</h2><?php if(!$applications):?><p>No hay solicitudes registradas.</p><?php else:?><div class="account-application-list"><?php foreach($applications as $application):?><article class="account-application-item"><strong><?=esc($application['business_name'])?></strong><p><?=esc($application['destination_name'])?> · <?=esc($application['category_label'])?> · <?=esc($application['application_type']==='claim_existing'?'Negocio registrado':'Nuevo negocio por validar')?></p><small>Estado: <?=esc(['pending'=>'Pendiente de revisión','in_review'=>'En revisión','not_approved'=>'No aprobada','approved'=>'Aprobada; negocio asociado'][$application['status']]??$application['status'])?> · <?=esc($application['created_at'])?></small></article><?php endforeach ?></div><?php endif ?></section>
<section class="destination-admin-list"><h2>Estado de tus pagos</h2><?php if(!$paymentHistory):?><p>Aquí verás el estado de cada comprobante que envíes.</p><?php else:?><div class="destination-admin-table"><table><thead><tr><th>Negocio</th><th>Suscripción e importe esperado</th><th>Estado</th><th>Enviado</th><th>Respuesta y siguiente paso</th></tr></thead><tbody><?php foreach($paymentHistory as $payment):?><tr><td><?=esc($payment['business_name']??'Negocio')?><?php if(!empty($payment['destination_name'])):?><br><small><?=esc($payment['destination_name'])?></small><?php endif ?></td><td><?=esc($payment['plan_name'])?> · <?=esc($payment['billing_frequency']?:'Gratis')?><br><small><?=esc($payment['quoted_amount']===null?'Sin cobro':number_format((float)$payment['quoted_amount'],0,',','.').' '.($payment['currency']??'COP'))?></small></td><td><?=esc(['pending'=>'Pendiente de revisión','approved'=>'Pago confirmado','rejected'=>'Comprobante rechazado'][$payment['status']]??$payment['status'])?></td><td><?=esc($payment['submitted_at'])?></td><td><?php if($payment['status']==='pending'):?>Estamos verificando el soporte. La suscripción aún no está activa.<?php elseif($payment['status']==='approved'):?>Pago confirmado. El negocio todavía requiere aprobación de publicación.<?php else:?>Revisa el motivo y envía un nuevo soporte válido desde el formulario de esta página.<?php endif ?><?php if(trim((string)$payment['customer_message'])!==''):?><br><small>Mensaje del equipo: <?=esc($payment['customer_message'])?></small><?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
<?php if($claims):?><section class="destination-admin-list"><h2>Solicitudes de representación anteriores</h2><div class="destination-admin-table"><table><thead><tr><th>Negocio</th><th>Destino</th><th>Estado</th><th>Fecha</th></tr></thead><tbody><?php foreach($claims as $claim):?><tr><td><?=esc($claim['display_name'])?></td><td><?=esc($claim['destination_name'])?></td><td><?=esc($claim['status'])?></td><td><?=esc($claim['created_at'])?></td></tr><?php endforeach ?></tbody></table></div></section><?php endif ?>
<section class="destination-admin-list"><h2>Visibilidad de tus negocios · últimos 30 días</h2><p>Conteos diarios sin cookies, no personas únicas. Una aparición requiere que al menos la mitad de la tarjeta sea visible durante un segundo; un clic hacia la página propia se cuenta como máximo una vez por tarjeta y carga. No representan ventas.</p><?php $audienceService=new BasicAudienceService(db(),dirname(__DIR__));foreach($businesses as $business):$audience=$audienceService->entityReport('business',$business['public_id']);?><h3><?=esc($business['display_name'])?></h3><?php if($business['publication_status']!=='published'):?><p>Actualmente no está publicado; no registra nuevas apariciones públicas.</p><?php endif ?><?php if($audience['status']!=='enabled'):?><p>Estadísticas pendientes de activación.</p><?php else:$metrics=$audience['metrics'];?><ul><li>Páginas propias vistas: <?=esc($metrics['page_views'])?></li><li>Apariciones de tarjeta en el directorio: <?=esc($metrics['directory_impressions'])?></li><li>Apariciones de tarjeta destacada: <?=esc($metrics['featured_impressions'])?></li><li>Clics hacia la página propia: <?=esc($metrics['profile_clicks'])?></li></ul><p>Registrado desde <?=esc(substr($audience['started_at'],0,10))?>.</p><?php if(($audience['optional']['status']??'')==='enabled'):?><p>Clics de contacto medidos con permiso: <?=esc($audience['optional']['contact_clicks'])?>. Esta muestra no representa todos los contactos ni ventas.</p><?php endif ?><details><summary>Detalle de días con actividad</summary><?php if(!$audience['trend']):?><p>Sin actividad registrada en este periodo.</p><?php else:?><div class="destination-admin-table"><table><thead><tr><th>Día</th><th>Página propia</th><th>Tarjeta</th><th>Destacado</th><th>Clics a página</th></tr></thead><tbody><?php foreach($audience['trend'] as $day=>$counts):?><tr><td><?=esc($day)?></td><td><?=esc($counts['page_views']??0)?></td><td><?=esc($counts['directory_impressions']??0)?></td><td><?=esc($counts['featured_impressions']??0)?></td><td><?=esc($counts['profile_clicks']??0)?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></details><?php endif;endforeach?></section>
<section class="destination-admin-list"><h2>Elegir suscripción y enviar soporte de pago</h2><?php if($paymentError):?><p class="notice" role="alert"><?=esc($paymentError)?></p><?php endif ?><?php if(($_GET['pago']??'')==='enviado'):?><p class="notice" role="status">Recibimos el soporte. La suscripción está pendiente de revisión; el negocio no se publica automáticamente.</p><?php endif ?><?php if(!$businesses):?><p>Esta opción aparecerá cuando el administrador apruebe una solicitud y asocie un negocio a tu cuenta.</p><?php else:?><p>El monto se calcula con la tarifa guardada. Solicita las instrucciones oficiales de transferencia a <a href="mailto:<?=esc($paymentContact)?>"><?=esc($paymentContact)?></a> antes de pagar. El comprobante será privado y el equipo lo revisará por separado.</p><?php foreach($businesses as $business):?><form method="post" enctype="multipart/form-data" class="destination-editor account-payment-form"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="business_id" value="<?=esc($business['id'])?>"><h3><?=esc($business['display_name'])?> · <?=esc($business['destination_name'])?></h3><div class="destination-form-grid"><label>Suscripción<select name="plan_code" required><?php foreach($plans as $plan):?><option value="<?=esc($plan['code'])?>"><?=esc($plan['name'])?><?php if(!empty($plan['prices']['monthly']['amount'])):?> · $<?=number_format((float)$plan['prices']['monthly']['amount'],0,',','.') ?>/mes<?php if(!empty($plan['prices']['annual']['amount'])):?> · $<?=number_format((float)$plan['prices']['annual']['amount'],0,',','.') ?>/año<?php endif ?><?php endif ?></option><?php endforeach ?></select></label><label>Frecuencia<select name="billing_frequency"><option value="monthly">Mensual</option><option value="annual">Anual</option></select></label><div class="notice account-payment-quote">Valor de esta elección: <strong data-price-output>—</strong><small data-plan-requirements-output></small></div><label class="wide">Soporte de pago · PDF, JPG, PNG o WebP · máximo 8 MB<input type="file" name="payment_proof" accept="application/pdf,image/jpeg,image/png,image/webp"></label><label class="wide">Referencia de transferencia (opcional)<input name="payment_reference" maxlength="160"></label></div><button class="pill compact" type="submit">Enviar suscripción y soporte</button></form><?php endforeach ?><?php endif ?></section>
<?php $cancelBusinesses=array_filter($businesses,static fn($business)=>($business['subscription_status']??'')==='active'&&($business['plan_code']??'free')!=='free');if($finance->ready()&&$businesses):?><section class="destination-admin-list"><h2>Solicitar cancelación o no renovación</h2><p>Registra tu solicitud para que el equipo la atienda. El período pagado conserva su vigencia mientras se revisa; este envío no ejecuta devoluciones ni cancela pagos externos.</p><?php if(isset($_GET['cancelacion'])):?><p role="status">Solicitud registrada. Puedes consultar su estado aquí.</p><?php endif ?><?php if($cancelBusinesses):?><form method="post" class="registration-form"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="action" value="cancel_request"><label>Negocio<select name="business_id" required><?php foreach($cancelBusinesses as $business):?><option value="<?=esc($business['id'])?>"><?=esc($business['display_name'])?></option><?php endforeach ?></select></label><label>Motivo<select name="reason_code"><?php foreach(OperatingFinanceService::REASONS as $code=>$label):?><option value="<?=esc($code)?>"><?=esc($label)?></option><?php endforeach ?></select></label><label>Detalle opcional<textarea name="reason_text" maxlength="1000"></textarea></label><button class="pill">Enviar solicitud</button></form><?php else:?><p>No tienes una suscripción paga activa para solicitar su cancelación.</p><?php endif ?><?php $cancellationQuery=db()->prepare('SELECT reason_code,status,created_at,review_note FROM subscription_cancellation_requests WHERE account_id=? ORDER BY id DESC LIMIT 30');$cancellationQuery->execute([(int)$account['id']]);foreach($cancellationQuery as $request):?><p><?=esc($request['created_at'])?> · <?=esc(OperatingFinanceService::REASONS[$request['reason_code']]??$request['reason_code'])?> · <?=esc($request['status']==='pending'?'Pendiente de atención':'Atendida')?><?php if($request['review_note']):?><br><?=esc($request['review_note'])?><?php endif ?></p><?php endforeach ?></section><?php endif ?>
<section class="account-next-steps"><h2>Verificación y publicación</h2><p>Enviar una suscripción no confirma el pago ni publica el negocio. Tras validar el soporte y la información, el equipo preparará y aprobará el borrador por separado.</p></section></main><script src="<?=esc(site_path('/assets/business-subscriptions.js?v=1'))?>" defer></script></body></html>
